const fs=require('fs');
function patch(path,fn){const before=fs.readFileSync(path,'utf8');const after=fn(before);if(after===before)throw new Error(`No change applied: ${path}`);fs.writeFileSync(path,after);}
function replaceOnce(s,a,b,label){if(!s.includes(a))throw new Error(`Missing anchor: ${label}`);return s.replace(a,b);}

for (const page of ['public/index.html','public/dashboard.html','public/admin-dashboard.html','public/observer-dashboard.html']) {
  patch(page,s=>{
    if(!s.includes('20260906-engagement1')) throw new Error(`Missing engagement1 cache token in ${page}`);
    s=s.replaceAll('20260906-engagement1','20260906-engagement2');
    if(page==='public/dashboard.html') s=replaceOnce(s,'<div id="studentAvatar" class="student-avatar">?</div>','<div id="studentAvatar" class="student-avatar"><span class="student-avatar-initial" aria-hidden="true">?</span></div>','stable avatar fallback');
    return s;
  });
}

patch('public/js/dashboard.js',s=>{
  const old=`    document.getElementById('navStudentPrn').innerText = \`PRN: \${student.prn}\`;\n    document.getElementById('studentAvatar').innerText = student.name ? student.name.charAt(0).toUpperCase() : 'S';\n    if ('requestIdleCallback' in window) {`;
  const repl=`    document.getElementById('navStudentPrn').innerText = \`PRN: \${student.prn}\`;\n    const avatarInitial = document.querySelector('#studentAvatar .student-avatar-initial');\n    if (avatarInitial) avatarInitial.textContent = student.name ? student.name.charAt(0).toUpperCase() : 'S';\n    // The engagement layer owns rank overlays inside #studentAvatar. Never replace the\n    // avatar element's full text/content here or the tap/hover reveal gets destroyed.\n    window.queueMicrotask?.(() => window.PortalStudentExperience?.refreshStudentExperience?.(data));\n    if ('requestIdleCallback' in window) {`;
  return replaceOnce(s,old,repl,'dashboard avatar mutation');
});

patch('public/js/student-experience-v1.js',s=>{
  const oldBoot=`  async function bootStudent() {\n    renderMuteToggle();\n    wrapSuccessToasts();\n    wrapFetchFeedback();\n    try {\n      const [profile, context, competitions, notifications] = await Promise.all([\n        api('/api/student/profile'), api('/api/student/engagement/context'), api('/api/student/competitions').catch(() => []), api('/api/student/workflow/notifications').catch(() => [])\n      ]);\n      currentContext = context;\n      currentCompletion = completionModel(profile);\n      document.body.dataset.profileMood = mood(currentCompletion);\n      installGreeting(profile);\n      installStudentAvatar(profile, context, currentCompletion);\n      installEmptyStates(profile);\n      installSinceLast(profile, context, competitions, notifications);\n      milestoneCheck(context);\n    } catch (error) { console.warn('Student experience enhancements unavailable:', error.message); }\n  }`;
  const newBoot=`  let refreshPromise = null;\n  async function refreshStudentExperience(profile = null) {\n    if (refreshPromise) return refreshPromise;\n    refreshPromise = (async () => {\n      try {\n        profile ||= await api('/api/student/profile');\n      } catch (error) {\n        console.warn('Student experience profile unavailable:', error.message);\n        return;\n      }\n      currentCompletion = completionModel(profile);\n      document.body.dataset.profileMood = mood(currentCompletion);\n      installGreeting(profile);\n      installEmptyStates(profile);\n\n      // Rank decoration is optional, never a single point of failure for the rest of the dashboard.\n      // Retry once because this request competes with initial profile/avatar requests on mobile.\n      let context = null;\n      try { context = await api('/api/student/engagement/context'); }\n      catch (_) { try { await new Promise(resolve => setTimeout(resolve, 180)); context = await api('/api/student/engagement/context'); } catch (error) { console.warn('Rank frame data unavailable:', error.message); } }\n      if (context) {\n        currentContext = context;\n        installStudentAvatar(profile, context, currentCompletion);\n        milestoneCheck(context);\n      } else {\n        installStudentAvatar(profile, null, currentCompletion);\n      }\n\n      const [competitionsResult, notificationsResult] = await Promise.allSettled([\n        api('/api/student/competitions'), api('/api/student/workflow/notifications')\n      ]);\n      installSinceLast(profile, context || currentContext, competitionsResult.status === 'fulfilled' ? competitionsResult.value : [], notificationsResult.status === 'fulfilled' ? notificationsResult.value : []);\n    })().finally(() => { refreshPromise = null; });\n    return refreshPromise;\n  }\n\n  function bootStudent() {\n    renderMuteToggle();\n    wrapSuccessToasts();\n    wrapFetchFeedback();\n    // dashboard.js owns the authoritative profile fetch and calls refreshStudentExperience(data).\n    // A delayed fallback keeps enhancements available if that base render path ever fails to call us.\n    setTimeout(() => { if (!currentCompletion) refreshStudentExperience(); }, 1200);\n  }`;
  s=replaceOnce(s,oldBoot,newBoot,'resilient engagement boot');
  const oldExport=`  window.PortalStudentExperience = { applyFrame, decorateCandidateProfile, feedback, installLoginAmbient };`;
  const newExport=`  window.PortalStudentExperience = { applyFrame, decorateCandidateProfile, feedback, installLoginAmbient, refreshStudentExperience };\n  document.dispatchEvent(new CustomEvent('portal:student-experience-ready'));`;
  return replaceOnce(s,oldExport,newExport,'experience export');
});

patch('public/css/student-experience-v1.css',s=>{
  const anchor=`.student-avatar[data-rank-reveal] { cursor:pointer; min-width:44px; min-height:44px; overflow:hidden; }`;
  const addition=`.student-avatar-initial { position:relative; z-index:1; }\n.student-avatar.has-image .student-avatar-initial { opacity:0; }\n${anchor}`;
  s=replaceOnce(s,anchor,addition,'avatar initial styles');
  return s+`\n/* Explicit scoring-rules control avoids native <details> interaction regressions on mobile. */\n.ranking-rules-toggle { width:100%; min-height:44px; display:flex; align-items:center; justify-content:space-between; gap:var(--space-sm); padding:var(--space-md); border:0; background:transparent; color:var(--text-heading); font:inherit; font-weight:700; text-align:left; cursor:pointer; }\n.ranking-rules-toggle::after { content:'+'; color:var(--primary); font-size:1.35rem; line-height:1; }\n.ranking-rules-toggle[aria-expanded='true']::after { content:'−'; }\n.ranking-rules-toggle:focus-visible { outline:3px solid var(--primary); outline-offset:-3px; }\n.ranking-rules-panel { padding:0 var(--space-md) var(--space-md); }\n.ranking-rules-panel[hidden] { display:none !important; }\n`;
});

patch('public/js/profile-ranking.js',s=>{
  s=replaceOnce(s,'        <details class="glass-card ranking-rules"><summary>How Profile Points work</summary><div id="rankingRules"></div></details>','        <section class="glass-card ranking-rules"><button id="rankingRulesToggle" class="ranking-rules-toggle" type="button" aria-expanded="false" aria-controls="rankingRules">How Profile Points work</button><div id="rankingRules" class="ranking-rules-panel" hidden></div></section>','ranking rules markup');
  const anchor=`    document.getElementById('rankingShowMore').addEventListener('click', () => { visibleCount += PAGE_SIZE; renderFiltered(false); });\n    panel.querySelectorAll('.leaderboard-scope').forEach(button => button.addEventListener('click', () => applyScope(button.dataset.scope)));`;
  const replacement=`    document.getElementById('rankingShowMore').addEventListener('click', () => { visibleCount += PAGE_SIZE; renderFiltered(false); });\n    const rulesToggle = document.getElementById('rankingRulesToggle');\n    const rulesPanel = document.getElementById('rankingRules');\n    rulesToggle.addEventListener('click', () => {\n      const open = rulesToggle.getAttribute('aria-expanded') !== 'true';\n      rulesToggle.setAttribute('aria-expanded', String(open));\n      rulesPanel.hidden = !open;\n    });\n    panel.querySelectorAll('.leaderboard-scope').forEach(button => button.addEventListener('click', () => applyScope(button.dataset.scope)));`;
  return replaceOnce(s,anchor,replacement,'ranking rules interaction');
});

patch('test/student-engagement-features.test.js',s=>{
  s=replaceOnce(s,/student-experience-v1\\.css\\\?v=20260906-engagement1/.source,/student-experience-v1\\.css\\\?v=20260906-engagement2/.source,'engagement css version test');
  s=replaceOnce(s,/student-experience-v1\\.js\\\?v=20260906-engagement1/.source,/student-experience-v1\\.js\\\?v=20260906-engagement2/.source,'engagement js version test');
  return s+`\n\ntest('engagement audit keeps avatar overlay stable and rank failure non-fatal', () => {\n  const dashboard = fs.readFileSync(path.join(__dirname,'../public/dashboard.html'),'utf8');\n  const dashboardJs = fs.readFileSync(path.join(__dirname,'../public/js/dashboard.js'),'utf8');\n  const experience = fs.readFileSync(path.join(__dirname,'../public/js/student-experience-v1.js'),'utf8');\n  assert.match(dashboard,/student-avatar-initial/);\n  assert.doesNotMatch(dashboardJs,/getElementById\\('studentAvatar'\\)\\.innerText/);\n  assert.match(dashboardJs,/refreshStudentExperience/);\n  assert.match(experience,/async function refreshStudentExperience/);\n  assert.match(experience,/Rank frame data unavailable/);\n  assert.match(experience,/Promise\\.allSettled/);\n  assert.match(experience,/if \\(refreshPromise\\) return refreshPromise/);\n  assert.doesNotMatch(experience,/const \\[profile, context, competitions, notifications\\] = await Promise\\.all/);\n});\n\ntest('profile point rules use explicit mobile-safe button disclosure', () => {\n  const ranking = fs.readFileSync(path.join(__dirname,'../public/js/profile-ranking.js'),'utf8');\n  assert.match(ranking,/id=\\"rankingRulesToggle\\"/);\n  assert.match(ranking,/aria-controls=\\"rankingRules\\"/);\n  assert.match(ranking,/rulesPanel\\.hidden = !open/);\n  assert.doesNotMatch(ranking,/<details class=\\"glass-card ranking-rules\\">/);\n});\n`;
});
